sys_ws_operation.operation_script:
(function process(request, response) {

    var requestBody = request.body.data;

    var complaint = new GlideRecord('x_snc_environmen_0_complaint');

    complaint.initialize();

    complaint.complaint_title = requestBody.complaint_title;
    complaint.description = requestBody.description;
    complaint.complaint_type = requestBody.complaint_type;
    complaint.pollution_category = requestBody.pollution_category;
    complaint.location = requestBody.location;
    complaint.complaint_source = "voice";

    if (requestBody.citizen_name) {
        complaint.citizen_name = requestBody.citizen_name;
    }

    if (requestBody.phone_number) {
        complaint.phone_number = requestBody.phone_number;
    }

    if (requestBody.email_address) {
        complaint.email_address = requestBody.email_address;
    }

    var sys_id = complaint.insert();

    if (sys_id) {

        response.setStatus(201);

        response.setBody({
            success: true,
            message: "Environmental complaint created successfully",
            complaint_number: complaint.number,
            sys_id: sys_id
        });

    } else {

        response.setStatus(500);

        response.setBody({
            success:false,
            message:"Unable to create complaint"
        });

    }

})(request, response);
